import{_ as a,a as r,c as t,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"树与区间结构","description":"按访问顺序、键检索、子树汇总、动态区间和与集合合并组织树结构；旋转示例与完整平衡树实现分清边界。","frontmatter":{"title":"树与区间结构","description":"按访问顺序、键检索、子树汇总、动态区间和与集合合并组织树结构；旋转示例与完整平衡树实现分清边界。","generated":"consolidation-v2","showdocs":{"topics":[{"id":"data-structures","title":"数据结构","link":"/topics/data-structures/"},{"id":"go","title":"Go","link":"/topics/go/"}],"kind":"系统学习","scope":"general","audience":"general","group":"原理与设计","summary":"按访问顺序、键检索、子树汇总、动态区间和与集合合并组织树结构；旋转示例与完整平衡树实现分清边界。","status":"active","related":[{"title":"并查集","link":"/principles/data-structures/trees/union-find","kind":"系统学习","scope":"general","audience":"general"},{"title":"层序遍历","link":"/principles/data-structures/trees/tree-level-order","kind":"系统学习","scope":"general","audience":"general"},{"title":"差分数组","link":"/principles/data-structures/structures/difference-array","kind":"系统学习","scope":"general","audience":"general"},{"title":"堆","link":"/principles/data-structures/structures/heap","kind":"系统学习","scope":"general","audience":"general"},{"title":"队列","link":"/principles/data-structures/structures/queue","kind":"系统学习","scope":"general","audience":"general"}],"prev":{"text":"树的直径","link":"/principles/data-structures/trees/tree-diameter"},"next":{"text":"树状数组","link":"/principles/data-structures/trees/fenwick-tree"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"树的直径","link":"/principles/data-structures/trees/tree-diameter"},"next":{"text":"树状数组","link":"/principles/data-structures/trees/fenwick-tree"}},"headers":[],"relativePath":"principles/data-structures/trees/algorithms-trees-general-general.md","filePath":"principles/data-structures/trees/algorithms-trees-general-general.md"}'),s={name:"principles/data-structures/trees/algorithms-trees-general-general.md"};function d(i,e,p,c,l,o){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="树与区间结构" tabindex="-1">树与区间结构 <a class="header-anchor" href="#树与区间结构" aria-label="Permalink to &quot;树与区间结构&quot;">​</a></h1><p>本页按场景选择方法；通过各条目链接阅读完整推演、源码和输出。</p><p>各段代码都是独立 main.go，Node 等同名类型不能合并。Go 1.22+，新建模块后一次只保存一个示例；本轮未执行。树必须有限且无环，旋转前要求对应孩子非 nil，DSU 下标须合法，线段树查询范围不得超出原输入长度；这些简例不统一进行输入校验。</p><table tabindex="0"><thead><tr><th>要解决的问题</th><th>可选方法</th><th>选择前确认</th></tr></thead><tbody><tr><td>逐层展示、复制结构或汇总子树</td><td><a href="#entry-tree-level-order-b7db0d4a5f">层序遍历</a>、<a href="#entry-tree-preorder-c5eadad473">前序遍历</a>、<a href="#entry-tree-inorder-4fe42f354c">中序遍历</a>、<a href="#entry-tree-postorder-956b7d1d36">后序遍历</a></td><td>层序用队列；中序仅在二叉搜索树上给出有序序列，后序先处理孩子。</td></tr><tr><td>维护有序键，或理解搜索树退化</td><td><a href="#entry-binary-search-tree-66cacd8922">二叉搜索树</a>与<a href="#entry-balanced-tree-c1c6ff731f">平衡树基础</a></td><td>普通搜索树最坏退化为 O(n)；旋转函数本身还不是完整 AVL 或红黑树。</td></tr><tr><td>沿字符串前缀组织检索</td><td><a href="#entry-trie-2019322a34">Trie 前缀树</a></td><td>耗时随单词长度增长；字符集很大时映射和指针的内存开销明显。</td></tr><tr><td>寻找祖先关系或树中最长路径</td><td><a href="#entry-lowest-common-ancestor-e6ec031cbe">最近公共祖先</a>或<a href="#entry-tree-diameter-a40b666e9a">树的直径</a></td><td>公共祖先示例假设目标都在树中；直径按边数计，空树为零。</td></tr><tr><td>在线更新数值并查询区间聚合</td><td><a href="#entry-fenwick-tree-8faae50d7d">树状数组</a>或<a href="#entry-segment-tree-3d52b6d49d">线段树</a></td><td>树状数组适合单点更新和前缀和；线段树示例提供区间和查询，更新需沿叶到根维护。</td></tr><tr><td>动态合并集合并判断连通</td><td><a href="#entry-union-find-4327b4bb74">并查集</a></td><td>路径压缩与按秩合并加速查询；普通并查集不支持高效拆分集合。</td></tr></tbody></table><h2 id="scene-visit-tree" tabindex="-1">按层、父子顺序访问树节点 <a class="header-anchor" href="#scene-visit-tree" aria-label="Permalink to &quot;按层、父子顺序访问树节点 {#scene-visit-tree}&quot;">​</a></h2><h3 id="entry-tree-level-order-b7db0d4a5f" tabindex="-1">层序遍历 <a class="header-anchor" href="#entry-tree-level-order-b7db0d4a5f" aria-label="Permalink to &quot;层序遍历 {#entry-tree-level-order-b7db0d4a5f}&quot;">​</a></h3><p><span id="输出"></span><span id="示例"></span></p><p><span id="entry-tree-level-order-b7db0d4a5f-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/trees/tree-level-order">层序遍历</a>。</p><p>队列先装入根节点，每取出一个节点就把它的孩子按顺序放到队尾。这样可以保证所有同层节点先于下一层被处理。 时间 O(n)。</p><p>若要按层分组，可以在每轮记录当前队列长度，再处理恰好这些节点。</p><h3 id="entry-tree-preorder-c5eadad473" tabindex="-1">前序遍历 <a class="header-anchor" href="#entry-tree-preorder-c5eadad473" aria-label="Permalink to &quot;前序遍历 {#entry-tree-preorder-c5eadad473}&quot;">​</a></h3><p><span id="输出-1"></span><span id="示例-1"></span></p><p><span id="entry-tree-preorder-c5eadad473-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/trees/tree-preorder">前序遍历</a>。</p><p>递归实现清晰，但极深的树会增加调用栈；也可以用显式栈迭代。</p><h3 id="entry-tree-inorder-4fe42f354c" tabindex="-1">中序遍历 <a class="header-anchor" href="#entry-tree-inorder-4fe42f354c" aria-label="Permalink to &quot;中序遍历 {#entry-tree-inorder-4fe42f354c}&quot;">​</a></h3><p><span id="输出-2"></span><span id="示例-2"></span></p><p><span id="entry-tree-inorder-4fe42f354c-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/trees/tree-inorder">中序遍历</a>。</p><p>普通二叉树并不具备这个有序性质，遍历顺序本身不会排序数据。</p><h3 id="entry-tree-postorder-956b7d1d36" tabindex="-1">后序遍历 <a class="header-anchor" href="#entry-tree-postorder-956b7d1d36" aria-label="Permalink to &quot;后序遍历 {#entry-tree-postorder-956b7d1d36}&quot;">​</a></h3><p><span id="输出-3"></span><span id="示例-3"></span></p><p><span id="entry-tree-postorder-956b7d1d36-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/trees/tree-postorder">后序遍历</a>。</p><p>每个节点只访问一次，时间 O(n)，递归栈与树高度相关。</p><h2 id="scene-index-keys" tabindex="-1">按键或字符串前缀建立索引 <a class="header-anchor" href="#scene-index-keys" aria-label="Permalink to &quot;按键或字符串前缀建立索引 {#scene-index-keys}&quot;">​</a></h2><h3 id="entry-binary-search-tree-66cacd8922" tabindex="-1">二叉搜索树 <a class="header-anchor" href="#entry-binary-search-tree-66cacd8922" aria-label="Permalink to &quot;二叉搜索树 {#entry-binary-search-tree-66cacd8922}&quot;">​</a></h3><p><span id="输出-4"></span><span id="示例-4"></span></p><p><span id="entry-binary-search-tree-66cacd8922-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/trees/binary-search-tree">二叉搜索树</a>。</p><p>插入时从根比较，小值走左、大值走右，直到找到空位置。搜索和插入平均只经过树的高度，但有序输入可能把普通树退化成链表。 平均查找 O(log n)，退化时 O(n)。</p><p>需要稳定对数复杂度时，应使用 AVL、红黑树等平衡结构。</p><h3 id="entry-balanced-tree-c1c6ff731f" tabindex="-1">平衡树基础 <a class="header-anchor" href="#entry-balanced-tree-c1c6ff731f" aria-label="Permalink to &quot;平衡树基础 {#entry-balanced-tree-c1c6ff731f}&quot;">​</a></h3><p><span id="输出-5"></span><span id="示例-5"></span></p><p><span id="entry-balanced-tree-c1c6ff731f-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/trees/balanced-tree">平衡树基础</a>。</p><p>右旋把左孩子提升为局部根，原根变成它的右孩子；左旋操作对称。旋转保持所有节点的中序顺序，因而不会破坏搜索树性质。 AVL、红黑树还需在旋转之外维护平衡约束。</p><p>仅有旋转函数还不是完整平衡树，插入或删除后还需维护高度或颜色约束。</p><h3 id="entry-trie-2019322a34" tabindex="-1">Trie 前缀树 <a class="header-anchor" href="#entry-trie-2019322a34" aria-label="Permalink to &quot;Trie 前缀树 {#entry-trie-2019322a34}&quot;">​</a></h3><p><span id="输出-6"></span><span id="示例-6"></span></p><p><span id="entry-trie-2019322a34-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/trees/trie">Trie 前缀树</a>。</p><p>从根到节点的路径对应一个字符串前缀，相同前缀只存储一次。Insert 缺少边时创建新节点，Has 逐字符跟随边并检查结束标记。 插入和查询耗时与单词长度成正比。</p><p>它适合前缀检索；字符集很大时，节点中的映射和指针会带来明显内存开销。</p><h2 id="scene-aggregate-subtrees" tabindex="-1">汇总子树以求公共祖先与最长路径 <a class="header-anchor" href="#scene-aggregate-subtrees" aria-label="Permalink to &quot;汇总子树以求公共祖先与最长路径 {#scene-aggregate-subtrees}&quot;">​</a></h2><h3 id="entry-lowest-common-ancestor-e6ec031cbe" tabindex="-1">最近公共祖先 <a class="header-anchor" href="#entry-lowest-common-ancestor-e6ec031cbe" aria-label="Permalink to &quot;最近公共祖先 {#entry-lowest-common-ancestor-e6ec031cbe}&quot;">​</a></h3><p><span id="输出-7"></span><span id="示例-7"></span></p><p><span id="entry-lowest-common-ancestor-e6ec031cbe-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/trees/lowest-common-ancestor">最近公共祖先</a>。</p><p>递归函数在子树中找到目标节点就返回该节点；如果左右子树各返回一个目标，当前节点就是最近公共祖先。若只在一侧找到结果，就继续向上返回它。 普通二叉树中时间 O(n)。</p><p>这个简化实现假设两个目标都属于树，否则需要额外验证。</p><h3 id="entry-tree-diameter-a40b666e9a" tabindex="-1">树的直径 <a class="header-anchor" href="#entry-tree-diameter-a40b666e9a" aria-label="Permalink to &quot;树的直径 {#entry-tree-diameter-a40b666e9a}&quot;">​</a></h3><p><span id="输出-8"></span><span id="示例-8"></span></p><p><span id="entry-tree-diameter-a40b666e9a-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/trees/tree-diameter">树的直径</a>。</p><p>每个节点返回本子树的高度，同时用左高度加右高度更新穿过当前节点的路径长度。所有节点候选取最大值得到以边数计的直径，时间 O(n)。</p><p>一次后序遍历即可完成；空树直径为零。</p><h2 id="scene-update-ranges" tabindex="-1">维护可变数据的前缀和与区间和 <a class="header-anchor" href="#scene-update-ranges" aria-label="Permalink to &quot;维护可变数据的前缀和与区间和 {#scene-update-ranges}&quot;">​</a></h2><h3 id="entry-fenwick-tree-8faae50d7d" tabindex="-1">树状数组 <a class="header-anchor" href="#entry-fenwick-tree-8faae50d7d" aria-label="Permalink to &quot;树状数组 {#entry-fenwick-tree-8faae50d7d}&quot;">​</a></h3><p><span id="输出-9"></span><span id="示例-9"></span></p><p><span id="entry-fenwick-tree-8faae50d7d-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/trees/fenwick-tree">树状数组</a>。</p><p>索引 i 的最低有效位决定当前节点负责的区间长度。Add 沿相关节点向上更新，Prefix 沿区间分解向前累加，因此两者都只经过对数个节点。 单点更新与前缀查询均为 O(log n)。</p><p>本例树状数组对外下标从 0 开始，内部加一才转成树状数组索引。NewFenwick(n) 要求 n 非负，Add 的外部下标必须在 [0,n)；Add(-1, delta) 会让内部索引及最低有效位都为 0，循环无法前进，必须在调用前拒绝。Prefix(i) 包含 i 处元素，允许 i=-1 表示空前缀，但不能令 i≥n。它适合单点更新和前缀和；复杂区间操作通常需要线段树。</p><h3 id="entry-segment-tree-3d52b6d49d" tabindex="-1">线段树 <a class="header-anchor" href="#entry-segment-tree-3d52b6d49d" aria-label="Permalink to &quot;线段树 {#entry-segment-tree-3d52b6d49d}&quot;">​</a></h3><p><span id="输出-10"></span><span id="示例-10"></span></p><p><span id="entry-segment-tree-3d52b6d49d-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/trees/segment-tree">线段树</a>。</p><p>叶节点存放原数组，内部节点保存左右子区间之和。查询半开区间 [l,r) 时，从两侧向上移动并累加被完整覆盖的节点。 区间查询与单点更新为 O(log n)。</p><p>构建需要 O(n) 时间与空间；示例展示区间和，单点更新可沿叶到根路径同步修改。</p><h2 id="scene-merge-components" tabindex="-1">合并集合并查询连通性 <a class="header-anchor" href="#scene-merge-components" aria-label="Permalink to &quot;合并集合并查询连通性 {#scene-merge-components}&quot;">​</a></h2><h3 id="entry-union-find-4327b4bb74" tabindex="-1">并查集 <a class="header-anchor" href="#entry-union-find-4327b4bb74" aria-label="Permalink to &quot;并查集 {#entry-union-find-4327b4bb74}&quot;">​</a></h3><p><span id="输出-11"></span><span id="示例-11"></span></p><p><span id="entry-union-find-4327b4bb74-完整解读"></span></p><p>正文、推演与完整示例：<a href="/principles/data-structures/trees/union-find">并查集</a>。</p><p>每个集合用一个代表根节点表示，Find 沿 parent 链寻找它。路径压缩缩短以后查询的路径，按秩合并避免树过高。 路径压缩与按秩合并使操作接近常数时间。</p><p>它擅长动态合并与连通性查询，但普通并查集不支持高效拆分已合并集合。</p><h2 id="review-exercise" tabindex="-1">静态自检 <a class="header-anchor" href="#review-exercise" aria-label="Permalink to &quot;静态自检 {#review-exercise}&quot;">​</a></h2><p>NewFenwick(4) 后 Add(0,3)、Add(2,5)，预测 Prefix(1) 与 Prefix(2)。提示：Prefix 的终点包含在和中。</p><details class="details custom-block"><summary>参考解法</summary><p>分别为 3、8；树状数组对外下标从 0 开始，内部才加一。不要把 Prefix(2) 理解成半开区间 [0,2)。</p></details>',81)])])}const f=a(s,[["render",d]]);export{u as __pageData,f as default};
